fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> Vec<f32> {
    // The mask and input must have the same length
    assert_eq!(a.len(), mask.len(), "Input and mask must have the same length");
    // Replacement values must be non-empty
    assert!(!values.is_empty(), "Replacement values must be non-empty");

    let n = a.len();
    let m = values.len();
    let mut result = Vec::with_capacity(n);

    for i in 0..n {
        if mask[i] {
            // Pick from `values`, wrapping around by modulo
            result.push(values[i % m]);
        } else {
            // Keep the original value
            result.push(a[i]);
        }
    }

    result
}

